# -*- coding: utf-8 -*-
"""El temario: 117 semanas en nueve estaciones de 13.

Es la guía para escribir cada semana (tools/curso/semanas/wNN.py): el título,
las ramas, qué tiene que cubrir y la fuente del seminario semanal.  Sale de
comparar los planes de estudio de las carreras de Filosofía (PLAN.md) y de
sumar lo que el curso quiere tener de más: las tradiciones no occidentales en
su momento (India y China junto a los presocráticos, el islam y el judaísmo
en el Medioevo, África y Asia hoy) y la literatura de cada corriente
(tools/curso/literatura.py).

TEMARIO = [{n, title, rama, cubre, seminario}]; las semanas de examen
(cada 13 y la última) tienen exam=True.
"""


def s(n, title, rama, cubre, seminario):
    return {"n": n, "title": title, "rama": rama, "cubre": cubre, "seminario": seminario, "exam": False}


def ex(n, title):
    return {"n": n, "title": title, "rama": [], "cubre": "Repaso de la estación por destreza: comprensión, conceptos, argumentos y contexto.",
            "seminario": "", "exam": True}


